const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const root_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "app", .root_module = root_module });
    b.installArtifact(exe);

    const tests = b.addTest(.{ .root_module = root_module });
    const test_step = b.step("test", "Run unit tests");
    test_step.dependOn(&b.addRunArtifact(tests).step);
}

//! `calc`: evaluate one signed 64-bit integer expression per input line.
//!
//! Parsing is iterative (operator precedence with explicit stacks), so deeply
//! nested input cannot exhaust the call stack.

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const Error = error{ Syntax, DivisionByZero, Overflow };

const Op = enum(u8) {
    add,
    sub,
    mul,
    div,
    rem,
    neg,
    /// An open parenthesis; acts as a barrier on the operator stack.
    paren,

    fn precedence(op: Op) u8 {
        return switch (op) {
            .paren => 0,
            .add, .sub => 1,
            .mul, .div, .rem => 2,
            .neg => 3,
        };
    }

    fn fromBinary(c: u8) ?Op {
        return switch (c) {
            '+' => .add,
            '-' => .sub,
            '*' => .mul,
            '/' => .div,
            '%' => .rem,
            else => null,
        };
    }
};

pub const Evaluator = struct {
    values: std.ArrayList(i64) = .empty,
    ops: std.ArrayList(Op) = .empty,

    pub fn deinit(e: *Evaluator, gpa: Allocator) void {
        e.values.deinit(gpa);
        e.ops.deinit(gpa);
        e.* = undefined;
    }

    /// Evaluates `src`, which must contain exactly one expression.
    pub fn eval(e: *Evaluator, gpa: Allocator, src: []const u8) (Error || Allocator.Error)!i64 {
        e.values.clearRetainingCapacity();
        e.ops.clearRetainingCapacity();

        var i: usize = 0;
        var expect_operand = true;
        while (true) {
            while (i < src.len and isBlank(src[i])) i += 1;
            if (i == src.len) break;
            const c = src[i];

            if (expect_operand) {
                switch (c) {
                    '-' => try e.ops.append(gpa, .neg),
                    '(' => try e.ops.append(gpa, .paren),
                    '0'...'9' => {
                        const start = i;
                        while (i < src.len and std.ascii.isDigit(src[i])) i += 1;
                        const value = std.fmt.parseInt(i64, src[start..i], 10) catch return error.Overflow;
                        try e.values.append(gpa, value);
                        expect_operand = false;
                        continue;
                    },
                    else => return error.Syntax,
                }
            } else if (c == ')') {
                while (true) {
                    const op = e.ops.pop() orelse return error.Syntax;
                    if (op == .paren) break;
                    try e.apply(op);
                }
            } else if (Op.fromBinary(c)) |op| {
                try e.reduce(op.precedence());
                try e.ops.append(gpa, op);
                expect_operand = true;
            } else {
                return error.Syntax;
            }
            i += 1;
        }

        if (expect_operand) return error.Syntax;
        try e.reduce(1);
        if (e.ops.items.len != 0) return error.Syntax; // unmatched '('
        std.debug.assert(e.values.items.len == 1);
        return e.values.items[0];
    }

    /// Applies stacked operators whose precedence is at least `min` (left associativity).
    fn reduce(e: *Evaluator, min: u8) Error!void {
        while (e.ops.getLastOrNull()) |op| {
            if (op.precedence() < min) break;
            _ = e.ops.pop();
            try e.apply(op);
        }
    }

    fn apply(e: *Evaluator, op: Op) Error!void {
        const values = &e.values;
        if (op == .neg) {
            const a = &values.items[values.items.len - 1];
            a.* = try std.math.negate(a.*);
            return;
        }
        const b = values.pop().?;
        const a = &values.items[values.items.len - 1];
        a.* = try binary(op, a.*, b);
    }
};

fn binary(op: Op, a: i64, b: i64) Error!i64 {
    return switch (op) {
        .add => std.math.add(i64, a, b),
        .sub => std.math.sub(i64, a, b),
        .mul => std.math.mul(i64, a, b),
        .div => if (b == 0)
            error.DivisionByZero
        else if (a == std.math.minInt(i64) and b == -1)
            error.Overflow
        else
            @divTrunc(a, b),
        .rem => if (b == 0)
            error.DivisionByZero
        else if (b == -1)
            0 // Avoids the trapping minInt % -1; the remainder is always 0.
        else
            @rem(a, b),
        .neg, .paren => unreachable,
    };
}

fn isBlank(c: u8) bool {
    return c == ' ' or c == '\t';
}

/// Evaluates every line of `input`, writing a value or `error` per non-blank line.
pub fn run(gpa: Allocator, input: []const u8, out: *std.Io.Writer) !void {
    var evaluator: Evaluator = .{};
    defer evaluator.deinit(gpa);

    var lines = std.mem.splitScalar(u8, input, '\n');
    while (lines.next()) |line| {
        if (std.mem.trim(u8, line, " \t").len == 0) continue;
        if (evaluator.eval(gpa, line)) |value| {
            try out.print("{d}\n", .{value});
        } else |err| switch (err) {
            error.OutOfMemory => return err,
            error.Syntax, error.DivisionByZero, error.Overflow => try out.writeAll("error\n"),
        }
    }
}

fn expectEval(src: []const u8, expected: Error!i64) !void {
    const gpa = std.testing.allocator;
    var e: Evaluator = .{};
    defer e.deinit(gpa);
    try std.testing.expectEqual(expected, e.eval(gpa, src));
}

test "arithmetic and precedence" {
    try expectEval("1 + 2 * 3", 7);
    try expectEval("(1 + 2) * 3", 9);
    try expectEval("1 + 2 * 3 - 4 / 2 % 3", 5);
    try expectEval("10 - 4 - 3", 3);
    try expectEval("--5", 5);
    try expectEval("-(2 + 3)", -5);
    try expectEval("2 * -3", -6);
    try expectEval("-2 * -3", 6);
    try expectEval("- 3 - - 2", -1);
}

test "division semantics" {
    try expectEval("-7 / 2", -3);
    try expectEval("-7 % 3", -1);
    try expectEval("7 % -3", 1);
    try expectEval("1 / 0", error.DivisionByZero);
    try expectEval("5 % 0", error.DivisionByZero);
    try expectEval("(-9223372036854775807 - 1) % -1", 0);
    try expectEval("(-9223372036854775807 - 1) / -1", error.Overflow);
}

test "overflow" {
    try expectEval("9223372036854775807 + 1", error.Overflow);
    try expectEval("9223372036854775808", error.Overflow);
    try expectEval("-9223372036854775808", error.Overflow);
    try expectEval("-(-9223372036854775807 - 1)", error.Overflow);
    try expectEval("3037000500 * 3037000500", error.Overflow);
    try expectEval("00009223372036854775807", 9223372036854775807);
}

test "syntax errors" {
    for ([_][]const u8{ "1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)", ")", "1 (2)", "2 -", "1 ** 2", "1\r" }) |src| {
        try expectEval(src, error.Syntax);
    }
}

test "deep nesting" {
    const gpa = std.testing.allocator;
    const depth = 100_000;
    const src = try gpa.alloc(u8, 2 * depth + 1);
    defer gpa.free(src);
    @memset(src[0..depth], '(');
    src[depth] = '7';
    @memset(src[depth + 1 ..], ')');
    try expectEval(src, 7);
}

//! `lru`: simulate a least-recently-used cache driven by text commands.
//!
//! Keys and values borrow from the input buffer, so the cache never copies
//! strings. Entries live in a slot array linked into a recency list by index;
//! a hash map from key to slot gives O(1) expected time per command.

const std = @import("std");
const Allocator = std.mem.Allocator;

const Index = u32;
const none = std.math.maxInt(Index);

const Slot = struct {
    key: []const u8,
    value: []const u8,
    prev: Index,
    next: Index,
};

pub const Cache = struct {
    capacity: usize,
    slots: std.ArrayList(Slot) = .empty,
    map: std.StringHashMapUnmanaged(Index) = .empty,
    /// Most recently used slot.
    head: Index = none,
    /// Least recently used slot.
    tail: Index = none,
    /// Slots released by `del`, chained through `next`.
    free: Index = none,
    /// Map removals since the last rehash; each one leaves a tombstone.
    tombstones: usize = 0,

    pub fn init(capacity: usize) Cache {
        std.debug.assert(capacity >= 1);
        return .{ .capacity = capacity };
    }

    pub fn deinit(c: *Cache, gpa: Allocator) void {
        c.slots.deinit(gpa);
        c.map.deinit(gpa);
        c.* = undefined;
    }

    pub fn size(c: *const Cache) usize {
        return c.map.count();
    }

    pub fn get(c: *Cache, key: []const u8) ?[]const u8 {
        const index = c.map.get(key) orelse return null;
        c.moveToFront(index);
        return c.slots.items[index].value;
    }

    pub fn set(c: *Cache, gpa: Allocator, key: []const u8, value: []const u8) Allocator.Error!void {
        const gop = try c.map.getOrPut(gpa, key);
        if (gop.found_existing) {
            const index = gop.value_ptr.*;
            c.slots.items[index].value = value;
            c.moveToFront(index);
            return;
        }

        const index: Index = if (c.map.count() > c.capacity) blk: {
            // Over capacity: recycle the least recently used slot for the new key.
            const victim = c.tail;
            c.unlink(victim);
            const removed = c.map.remove(c.slots.items[victim].key);
            std.debug.assert(removed);
            c.noteRemoval();
            break :blk victim;
        } else if (c.free != none) blk: {
            const reused = c.free;
            c.free = c.slots.items[reused].next;
            break :blk reused;
        } else blk: {
            const fresh: Index = @intCast(c.slots.items.len);
            c.slots.append(gpa, undefined) catch |err| {
                c.map.removeByPtr(gop.key_ptr);
                return err;
            };
            break :blk fresh;
        };

        // Removal only leaves a tombstone, so `gop` still points at the new entry.
        gop.value_ptr.* = index;
        c.slots.items[index] = .{ .key = key, .value = value, .prev = none, .next = none };
        c.pushFront(index);
    }

    /// Removes `key`; returns whether it was present.
    pub fn del(c: *Cache, key: []const u8) bool {
        const kv = c.map.fetchRemove(key) orelse return false;
        c.noteRemoval();
        c.unlink(kv.value);
        c.slots.items[kv.value].next = c.free;
        c.free = kv.value;
        return true;
    }

    /// Reserves map space for `count` keys with enough headroom that tombstones
    /// are purged by `noteRemoval` before they could force the map to grow.
    pub fn reserve(c: *Cache, gpa: Allocator, count: usize) Allocator.Error!void {
        try c.map.ensureTotalCapacity(gpa, @intCast(2 * count));
        try c.slots.ensureTotalCapacity(gpa, count);
    }

    /// Tombstones lengthen probe sequences and are only cleared by a rehash;
    /// rehashing after every capacity/8 removals keeps the cost amortized O(1).
    fn noteRemoval(c: *Cache) void {
        c.tombstones += 1;
        if (c.tombstones >= c.map.capacity() / 8) {
            c.map.rehash(std.hash_map.StringContext{});
            c.tombstones = 0;
        }
    }

    fn moveToFront(c: *Cache, index: Index) void {
        if (c.head == index) return;
        c.unlink(index);
        c.pushFront(index);
    }

    fn pushFront(c: *Cache, index: Index) void {
        const slot = &c.slots.items[index];
        slot.prev = none;
        slot.next = c.head;
        if (c.head != none) c.slots.items[c.head].prev = index else c.tail = index;
        c.head = index;
    }

    fn unlink(c: *Cache, index: Index) void {
        const slot = c.slots.items[index];
        if (slot.prev != none) c.slots.items[slot.prev].next = slot.next else c.head = slot.next;
        if (slot.next != none) c.slots.items[slot.next].prev = slot.prev else c.tail = slot.prev;
    }
};

pub const max_capacity = 1_000_000;

/// Runs the command script in `input` and writes command results to `out`.
pub fn run(gpa: Allocator, input: []const u8, out: *std.Io.Writer) !void {
    var lines = std.mem.splitScalar(u8, input, '\n');
    const first = trimCr(lines.first());
    const parsed = std.fmt.parseUnsigned(usize, std.mem.trim(u8, first, " \t"), 10) catch return;
    const capacity = std.math.clamp(parsed, 1, max_capacity);

    var cache: Cache = .init(capacity);
    defer cache.deinit(gpa);

    // Reserve up front: the map never holds more than capacity + 1 keys, and
    // there cannot be more keys than lines of input.
    const expected: usize = @min(capacity + 1, std.mem.count(u8, input, "\n") + 1);
    try cache.reserve(gpa, expected);

    while (lines.next()) |raw| {
        const line = trimCr(raw);
        var tokens = std.mem.splitScalar(u8, line, ' ');
        const op = tokens.first();
        if (std.mem.eql(u8, op, "SET")) {
            const key = tokens.next() orelse continue;
            const value = tokens.next() orelse continue;
            try cache.set(gpa, key, value);
        } else if (std.mem.eql(u8, op, "GET")) {
            const key = tokens.next() orelse continue;
            try out.print("{s}\n", .{cache.get(key) orelse "NULL"});
        } else if (std.mem.eql(u8, op, "DEL")) {
            const key = tokens.next() orelse continue;
            try out.writeAll(if (cache.del(key)) "1\n" else "0\n");
        } else if (std.mem.eql(u8, op, "SIZE")) {
            try out.print("{d}\n", .{cache.size()});
        }
    }
}

fn trimCr(line: []const u8) []const u8 {
    return if (std.mem.endsWith(u8, line, "\r")) line[0 .. line.len - 1] else line;
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    const gpa = std.testing.allocator;
    var out: std.Io.Writer.Allocating = .init(gpa);
    defer out.deinit();
    try run(gpa, input, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput("2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n", "1\nNULL\n2\n");
}

test "overwrite refreshes recency" {
    try expectOutput("2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c", "9\nNULL\n3\n");
}

test "delete, reuse and capacity one" {
    try expectOutput("3\nSET x 1\nDEL x\nDEL x\nSIZE\nGET x\nSET y 2\nSET z 3\nSIZE\n", "1\n0\n0\nNULL\n2\n");
    try expectOutput("1\nSET a 1\nSET b 2\nGET a\nGET b\nSIZE\n", "NULL\n2\n1\n");
}

//! `app`: a small suite of stdin-to-stdout tools selected by the first argument.

const std = @import("std");
const wordfreq = @import("wordfreq.zig");
const lru = @import("lru.zig");
const calc = @import("calc.zig");

const Command = enum { wordfreq, lru, calc };

const usage = "usage: app <wordfreq|lru|calc> < input\n";

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;

    var args = init.minimal.args.iterate();
    _ = args.next(); // program name
    const name = args.next() orelse fatal(io, usage);
    const command = std.meta.stringToEnum(Command, name) orelse fatal(io, usage);

    const input = try readStdin(io, gpa);
    defer gpa.free(input);

    var out_buf: [64 * 1024]u8 = undefined;
    var stdout = std.Io.File.stdout().writerStreaming(io, &out_buf);
    const out = &stdout.interface;

    switch (command) {
        .wordfreq => try wordfreq.run(gpa, input, out),
        .lru => try lru.run(gpa, input, out),
        .calc => try calc.run(gpa, input, out),
    }
    try out.flush();
}

fn readStdin(io: std.Io, gpa: std.mem.Allocator) ![]u8 {
    var in_buf: [64 * 1024]u8 = undefined;
    var stdin = std.Io.File.stdin().readerStreaming(io, &in_buf);
    return stdin.interface.allocRemaining(gpa, .unlimited);
}

fn fatal(io: std.Io, msg: []const u8) noreturn {
    std.Io.File.stderr().writeStreamingAll(io, msg) catch {};
    std.process.exit(2);
}

test {
    std.testing.refAllDecls(@This());
    _ = wordfreq;
    _ = lru;
    _ = calc;
}

//! `wordfreq`: print the ten most frequent ASCII-letter words of the input.

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const top_n = 10;

const Entry = struct {
    word: []const u8,
    count: u32,

    /// True when `a` ranks strictly before `b`: higher count first, then byte order.
    fn ranksBefore(a: Entry, b: Entry) bool {
        if (a.count != b.count) return a.count > b.count;
        return std.mem.lessThan(u8, a.word, b.word);
    }
};

/// Counts words in `input` and writes the top entries to `out`.
/// `input` is lowercased in place so that map keys can borrow from it.
pub fn run(gpa: Allocator, input: []u8, out: *std.Io.Writer) !void {
    var counts: std.StringHashMapUnmanaged(u32) = .empty;
    defer counts.deinit(gpa);

    var i: usize = 0;
    while (i < input.len) {
        if (!std.ascii.isAlphabetic(input[i])) {
            i += 1;
            continue;
        }
        const start = i;
        while (i < input.len and std.ascii.isAlphabetic(input[i])) : (i += 1) {
            input[i] |= 0x20; // ASCII letters: setting bit 5 lowercases.
        }
        const gop = try counts.getOrPut(gpa, input[start..i]);
        gop.value_ptr.* = if (gop.found_existing) gop.value_ptr.* + 1 else 1;
    }

    var top: [top_n]Entry = undefined;
    const ranked = selectTop(&counts, &top);
    for (ranked) |entry| try out.print("{d} {s}\n", .{ entry.count, entry.word });
}

/// Fills `top` with the best-ranked entries, in rank order, and returns the used prefix.
fn selectTop(counts: *const std.StringHashMapUnmanaged(u32), top: *[top_n]Entry) []Entry {
    var len: usize = 0;
    var it = counts.iterator();
    while (it.next()) |kv| {
        const candidate: Entry = .{ .word = kv.key_ptr.*, .count = kv.value_ptr.* };
        if (len == top_n and !candidate.ranksBefore(top[len - 1])) continue;
        // Insertion into the small sorted array, dropping the last entry if full.
        var pos = if (len < top_n) len else top_n - 1;
        while (pos > 0 and candidate.ranksBefore(top[pos - 1])) : (pos -= 1) {
            top[pos] = top[pos - 1];
        }
        top[pos] = candidate;
        if (len < top_n) len += 1;
    }
    return top[0..len];
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    const gpa = std.testing.allocator;
    const buf = try gpa.dupe(u8, input);
    defer gpa.free(buf);
    var out: std.Io.Writer.Allocating = .init(gpa);
    defer out.deinit();
    try run(gpa, buf, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput("The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n");
}

test "separators and empty input" {
    try expectOutput("don't stop_me 4now, now-NOW\xff", "3 now\n1 don\n1 me\n1 stop\n1 t\n");
    try expectOutput("", "");
    try expectOutput("123 \xc3\xa9 !!", "");
}

test "at most ten lines, ties by word" {
    try expectOutput(
        "zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha",
        "2 alpha\n1 beta\n1 eta\n1 iota\n1 kappa\n1 lambda\n1 mu\n1 nu\n1 omicron\n1 pi\n",
    );
}
